import {Showtime} from './showtime-ui.js';
import {captainLevel} from './showtime-rules.js';
import {TEAMS,RULES,TEAM_RECIPES,CoachingWindow,teamRecipe,kickoffCard,roundTimeline,decideWinner} from './clash.js';
import {MATCH_STEPS,startState} from './league.js';
import {clashKickoffPositions} from './clash-coordinates.js';
const $=id=>document.getElementById(id),gsap=window.gsap;
const NAMES={mint:'Mint',coral:'Coral'};
export class CoachClash{
 constructor(hooks){this.hooks=hooks;this.phase='idle';this.token=0;this.workers=[];this.coaching=new CoachingWindow();this.score={mint:0,coral:0};this.round=0;this.paused=false;
  const panel=document.createElement('section');panel.id='coach-clash';panel.className='clash-panel';panel.innerHTML=`<div class="clash-intro"><div><span class="eyebrow">THE MAIN EVENT · CHAT VS. CHAT</span><h2>Two teams. Sixteen tentacles.<br><em>One bragging right.</em></h2><p>Coach your creature. Call the winner. Opposite goals. One 120-move showdown.</p></div><div class="clash-start-actions"><button id="clash-start" class="btn mint">Start a chat showdown ↗</button><button id="clash-demo" class="plain">Try a local demo · no Twitch needed</button></div></div><div id="clash-session" hidden><div class="clash-phase-row"><span id="clash-phase" class="clash-phase">COACHING</span><strong id="clash-clock">30s</strong><span id="clash-round"></span><button id="clash-exit" class="plain">Return to solo lab ×</button></div><div class="clash-teams">${TEAMS.map(team=>`<article class="team-card ${team}"><div class="team-heading"><strong>TEAM ${team.toUpperCase()}</strong><span id="${team}-members">0 coaches</span></div><p>Join in chat: <code>!team ${team}</code></p><label for="${team}-recipe">Host recipe</label><select id="${team}-recipe">${Object.entries(TEAM_RECIPES).map(([key,r])=>`<option value="${key}">${r.name}</option>`).join('')}</select><div id="${team}-rules" class="team-rules"></div><div class="team-status"><span id="${team}-votes">0 votes</span><span id="${team}-training">Ready to coach</span></div><progress id="${team}-progress" max="10000" value="0" aria-label="${NAMES[team]} training progress"></progress></article>`).join('')}</div><div class="clash-instructions"><p id="clash-instructions">Join a team, then send <code>!reward goal 10</code> or <code>!reward touch 0</code>. Predict with <code>!predict mint</code> or <code>!predict coral</code>.</p><div><button id="clash-lock" class="btn mint">Lock recipes & train both ↗</button><button id="clash-pause" class="btn" hidden>Pause race</button><button id="clash-export" class="plain" hidden>Download round ↓</button></div></div><p id="clash-feed" class="clash-feed" role="status">Waiting for coaches.</p><div id="clash-result" class="clash-result" hidden><span class="eyebrow">THE RECEIPTS</span><h3 id="clash-verdict"></h3><p id="clash-insight"></p><div class="clash-result-actions"><button id="clash-repair" class="btn mint">Rematch · only 2 rule changes ↗</button><button id="clash-new" class="btn">Fresh round →</button><span id="clash-series"></span></div></div><p class="clash-fairness">Mirrored courses, equal training and move budgets. Mint attacks right; Coral attacks left. Each ball follows its own team-colored course; creatures do not collide. Goals decide; fewer mistakes break ties. Tied policies can draw.</p></div>`;
  $('play').before(panel);
  const hud=document.createElement('div');hud.id='clash-hud';hud.innerHTML=`<div class="clash-hud-team mint"><span>MINT →</span><strong id="mint-score">00</strong></div><div class="clash-hud-middle"><span id="clash-card-label">SEALED KICKOFF</span><strong id="clash-move">0 / 120</strong><small>OPPOSITE GOALS · GHOST RACE</small><small id="clash-captain-badge">NATIVE CONDITIONS</small></div><div class="clash-hud-team coral"><strong id="coral-score">00</strong><span>← CORAL</span></div>`;$('viewport').append(hud);const countdown=document.createElement('div');countdown.id='clash-countdown';countdown.setAttribute('aria-live','polite');$('viewport').append(countdown);
  const arenaPause=document.createElement('button');arenaPause.id='clash-arena-pause';arenaPause.textContent='Ⅱ';arenaPause.setAttribute('aria-label','Pause showdown');hud.append(arenaPause);arenaPause.onclick=()=>{if(this.phase==='playing')$('clash-pause').click();};
  $('clash-start').onclick=()=>this.start(false);$('clash-demo').onclick=()=>this.start(true);$('clash-exit').onclick=()=>this.cancel(true);$('clash-lock').onclick=()=>this.train();$('clash-repair').onclick=()=>this.start(false,true);$('clash-new').onclick=()=>this.start(false);$('clash-pause').onclick=()=>{this.paused=!this.paused;$('clash-pause').textContent=this.paused?'Resume race':'Pause race';arenaPause.textContent=this.paused?'▶':'Ⅱ';arenaPause.setAttribute('aria-label',this.paused?'Resume showdown':'Pause showdown');this.hooks.getScene()?.setPlaying(!this.paused);this.sendPacket(this.timeline.moves[this.move]);};$('clash-export').onclick=()=>this.export();for(const team of TEAMS)$(team+'-recipe').onchange=()=>{if(team==='coral'&&this.showtime?.guestJoined)return;this.recipes[team]={...TEAM_RECIPES[$(team+'-recipe').value].weights};this.renderRecipes();};
  for(const team of TEAMS){const option=document.createElement('option');option.value='custom';option.textContent='Chat recipe';option.disabled=true;$(team+'-recipe').append(option);}
  this.overlay=new URLSearchParams(location.search).has('overlay');this.sync=typeof BroadcastChannel==='function'?new BroadcastChannel('medusa-coach-clash'):null;if(this.sync)this.sync.onmessage=({data})=>{if(data.type==='tick'&&!this.overlay)this.advance(performance.now());if(data.type==='request'&&!this.overlay)this.sync.postMessage(this.lastPacket||{type:'end'});if(this.overlay&&data.type==='frame')this.receivePacket(data);if(this.overlay&&data.type==='end')this.cancel(false);};if(this.overlay)this.sync?.postMessage({type:'request'});
  this.showtime=this.overlay?null:new Showtime(this);
  this.frame=this.frame.bind(this);requestAnimationFrame(this.frame);window.addEventListener('beforeunload',()=>this.stop());
 }
 active(){return this.phase!=='idle';}
 start(demo=false,repair=false){
  if(this.showtime?.remote)return;
  const prior=this.policies,priorCard=this.card;this.stop();this.phase='coaching';this.countdown=null;this.paused=false;this.demo=demo;this.repair=repair;this.round++;this.showtime?.begin(repair);this.level=captainLevel(this.hooks.getLevel(),this.showtime?.locked||'native');this.hooks.getScene()?.load(this.level);this.recipes=Object.fromEntries(TEAMS.map(t=>[t,{...(repair&&prior?prior[t].weights:TEAM_RECIPES.balanced.weights)}]));this.base=structuredClone(this.recipes);if(demo)this.recipes.coral={...TEAM_RECIPES.chaos.weights};this.card=repair?priorCard:null;
  const members=this.coaching.members;this.coaching=new CoachingWindow();this.coaching.members=members;this.hooks.onStart();document.body.classList.add('clash-active');$('clash-session').hidden=false;$('clash-result').hidden=true;$('clash-start').hidden=true;$('clash-demo').hidden=true;$('clash-pause').hidden=true;$('clash-export').hidden=true;$('clash-lock').hidden=false;$('clash-lock').disabled=false;$('clash-lock').textContent='Lock recipes & train both ↗';$('clash-clock').textContent=demo?'DEMO':'30s';$('clash-phase').textContent=repair?'REPAIR WINDOW':'COACHING';$('clash-round').textContent=`ROUND ${this.round} · ${this.level.name}${demo?' · LOCAL DEMO':''}`;$('clash-card-label').textContent=repair?'SAME KICKOFF':'SEALED KICKOFF';$('clash-move').textContent='0 / 120';$('mint-score').textContent=$('coral-score').textContent='00';$('clash-feed').textContent=demo?'LOCAL DEMO: Mint rewards goals. Coral rewards touches. These are example recipes, not live viewer votes.':'Join with !team mint or !team coral. Team reward votes are open.';
  $('clash-instructions').innerHTML=repair?'Each team can change <strong>at most two reward components</strong>. Most-supported changes take priority. The kickoff stays the same so you can compare.':'Join a team, then send <code>!reward goal 10</code> or <code>!reward touch 0</code>. Call a winner with <code>!predict mint</code> / <code>!predict coral</code>.';
  for(const team of TEAMS){$(team+'-recipe').disabled=false;$(team+'-recipe').value=demo&&team==='coral'?'chaos':'balanced';$(team+'-training').textContent='Ready to coach';$(team+'-progress').value=0;}this.renderRecipes();this.renderCounts();this.hooks.getScene()?.showRival(true);const initial={state:startState(this.level),kind:'start'};this.hooks.getScene()?.setFrame(initial,.2,true);this.hooks.getScene()?.setRivalFrame(initial,.2,true);
  document.body.classList.remove('clash-racing');$('match-clock').textContent='0 / 120 MOVES';$('action-label').textContent='Coaches are choosing incentives.';this.sendPacket({mint:initial,coral:initial,move:0});if(demo){this.demoTimer=setTimeout(()=>this.train(),600);}else{this.deadline=Date.now()+30000;this.timer=setInterval(()=>{const left=Math.max(0,Math.ceil((this.deadline-Date.now())/1000));$('clash-clock').textContent=left+'s';if(!left)this.train();},200);}
 }
 renderCounts(){const counts=this.coaching.counts();for(const t of TEAMS){$(t+'-members').textContent=counts[t]+' coaches';$(t+'-votes').textContent=this.coaching.votes[t].size+' votes';}}
 renderRecipes(){for(const team of TEAMS){const result=teamRecipe(this.base[team],this.recipes[team],this.coaching.votes[team],this.repair?2:4);this.preview||={};this.preview[team]=result;$(team+'-rules').innerHTML=RULES.map(k=>`<span>${k.toUpperCase()} <b>${k==='safety'?'−':'+'}${result.weights[k]}</b></span>`).join('');$(team+'-recipe').value=Object.entries(TEAM_RECIPES).find(([,r])=>RULES.every(k=>r.weights[k]===result.weights[k]))?.[0]||'custom';if(this.repair)$(team+'-training').textContent=result.changes.length+'/2 changes'+(result.dropped.length?' · extra changes held back':'');}}
 handleChat(message){if(this.showtime?.routeChat(message))return true;if(!this.active())return false;if(this.showtime?.handleLocal(message))return true;const result=this.coaching.receive(message.user,message.text,this.phase);if(result.accepted){this.renderCounts();this.renderRecipes();$('clash-feed').textContent=result.type==='team'?`A coach joined Team ${NAMES[result.team]}.`:result.type==='predict'?`A viewer picked ${NAMES[result.team]} to win.`:`Team ${NAMES[result.team]} received ${result.rule} ${result.value}.`;}else if(result.reason)$('clash-feed').textContent=result.reason;return true;}
 async train(){if(this.phase!=='coaching'||this.showtime?.remote)return;this.showtime?.lockRecipes();this.showtime?.lockWorld();clearInterval(this.timer);clearTimeout(this.demoTimer);this.renderRecipes();this.recipes=Object.fromEntries(TEAMS.map(t=>[t,{...this.preview[t].weights}]));this.phase='training';$('clash-phase').textContent='TRAINING BOTH TEAMS';$('clash-clock').textContent='EQUAL SEED';$('clash-lock').disabled=true;$('clash-feed').textContent='Both teams start from empty Q-tables with seed 42 and 10,000 episodes. Recipes are locked.';for(const t of TEAMS)$(t+'-recipe').disabled=true;const token=this.token;
  try{const results=await Promise.all(TEAMS.map(team=>new Promise((resolve,reject)=>{const worker=new Worker('./league-worker.js',{type:'module'});this.workers.push(worker);worker.onmessage=({data})=>{if(token!==this.token)return;if(data.type==='progress'){$(team+'-progress').value=data.episode;$(team+'-training').textContent=data.episode.toLocaleString()+' / 10,000 episodes';}if(data.type==='complete'){worker.terminate();resolve({q:data.q,weights:data.weights,seed:data.seed,total:data.total,history:data.history});}if(data.type==='error')reject(new Error(data.message));};worker.onerror=()=>reject(new Error('A training worker could not start.'));worker.postMessage({levelId:this.level.id,captainRule:this.level.captainRule,weights:this.recipes[team],seed:42,total:10000});})));
   if(token!==this.token)return;this.workers=[];this.policies=Object.fromEntries(TEAMS.map((t,i)=>[t,results[i]]));if(!this.card){const seed=crypto.getRandomValues(new Uint32Array(1))[0];this.card=kickoffCard(this.level,seed);}this.timeline=roundTimeline(this.policies.mint,this.policies.coral,this.level,this.card);this.phase='countdown';$('clash-phase').textContent='KICKOFF REVEAL';$('clash-card-label').textContent=this.card.name;$('clash-feed').textContent=`${this.card.name}. Mint starts at (${this.card.position.join(', ')}); Coral at (${clashKickoffPositions(this.level,this.card.position).coral.join(', ')}). Opposite goals, mirrored conditions, world phase ${this.card.phase}. Predictions lock at GO.`;$('clash-lock').hidden=true;
   document.body.classList.add('clash-racing');$('play').scrollIntoView({behavior:'smooth',block:'start'});this.sendPacket(this.timeline.moves[0]);for(const number of ['3','2','1','GO!']){if(token!==this.token)return;this.countdown=number;this.sendPacket(this.timeline.moves[0]);$('clash-countdown').textContent=number;gsap.fromTo('#clash-countdown',{opacity:1,scale:.7},{opacity:0,scale:1.15,duration:.9});await new Promise(resolve=>setTimeout(resolve,1000));}if(token!==this.token)return;this.countdown=null;this.phase='playing';this.move=0;this.paused=false;this.last=performance.now();$('clash-phase').textContent='SHOWDOWN';$('clash-clock').textContent='LIVE';$('clash-pause').hidden=false;this.hooks.getScene()?.setPlaying(true);this.paintMove(0,true);
  }catch(error){if(token!==this.token)return;this.phase='error';$('clash-phase').textContent='TRAINING INTERRUPTED';$('clash-feed').textContent=error.message+' Return to solo or start a fresh round.';for(const w of this.workers)w.terminate();this.workers=[];$('clash-start').hidden=false;$('clash-demo').hidden=false;}
 }
 paintMove(move,immediate=false){const pair=this.timeline.moves[move],scene=this.hooks.getScene(),duration=Number($('speed').value)/1000;for(const team of TEAMS){const entry=pair[team];if(move>0&&this.timeline.moves[move-1][team].terminal){const previous=this.timeline.moves[move-1][team];const reset={state:{...previous.state,x:this.card.position[0],y:this.card.position[1]},kind:'reset'};if(team==='mint')scene?.setFrame(reset,duration,true);else scene?.setRivalFrame(reset,duration,true);}if(team==='mint')scene?.setFrame(entry,duration,immediate);else scene?.setRivalFrame(entry,duration,immediate);$(team+'-score').textContent=String(entry.state.goals).padStart(2,'0');if(entry.kind==='goal'&&!immediate)this.goal(team);}
  $('clash-move').textContent=move+' / 120';$('match-clock').textContent=move+' / 120 MOVES';$('action-label').textContent=pair.mint.state.goals===pair.coral.state.goals?'Neck and neck. Every goal counts.':`${pair.mint.state.goals>pair.coral.state.goals?'Mint':'Coral'} leads. Can the other recipe catch up?`;this.move=move;this.sendPacket(pair);
 }
 goal(team){this.hooks.onGoal?.(team);$('clash-countdown').textContent=NAMES[team].toUpperCase()+' SCORES!';$('clash-countdown').style.color=team==='mint'?'#75f7d4':'#ff9da9';gsap.killTweensOf('#clash-countdown');gsap.fromTo('#clash-countdown',{opacity:.95,scale:.85},{opacity:0,scale:1.1,duration:.75});gsap.fromTo('#'+team+'-score',{scale:1.5},{scale:1,duration:.4,ease:'back.out(2)'});}
 advance(now){if(this.phase!=='playing'||this.paused||now-this.last<Number($('speed').value))return;this.last=now;if(this.move<MATCH_STEPS)this.paintMove(this.move+1);else this.finish();}
 frame(now){requestAnimationFrame(this.frame);if(this.overlay){if(this.active()&&this.remotePhase==='playing'&&now-(this.lastTick||0)>75){this.lastTick=now;this.sync?.postMessage({type:'tick'});}return;}if(!document.hidden)this.advance(now);}
 finish(){this.showtime?.finish();this.phase='result';document.body.classList.remove('clash-racing');this.hooks.getScene()?.setPlaying(false);$('clash-phase').textContent='THE VERDICT';$('clash-clock').textContent='FULL TIME';$('clash-pause').hidden=true;$('clash-result').hidden=false;$('clash-export').hidden=false;const {winner,runs}=this.timeline;const a=runs.mint.stats,b=runs.coral.stats;if(winner.team)this.score[winner.team]++;$('clash-verdict').textContent=winner.team?`Team ${NAMES[winner.team]} wins. ${a.goals}–${b.goals}.`:`An honest draw. ${a.goals}–${b.goals}.`;
  let insight=`${winner.reason}. Mint made ${a.collisions} mistakes; Coral made ${b.collisions}. `;for(const t of TEAMS){const s=runs[t].stats;if(s.goals===0&&s.touches>50&&this.policies[t].weights.touch>0)insight+=`${NAMES[t]} rewarded touches +${this.policies[t].weights.touch}: ${s.touches} touches, zero goals. `;}const correct=winner.team?[...this.coaching.predictions.values()].filter(t=>t===winner.team).length:0;insight+=this.coaching.predictions.size?`${correct} of ${this.coaching.predictions.size} viewers called the winner.`:'Try !predict mint or !predict coral before the next kickoff.';$('clash-insight').textContent=insight;$('clash-series').textContent=`SESSION WINS · MINT ${this.score.mint} / CORAL ${this.score.coral}`;$('clash-feed').textContent='Want redemption? Each team gets only two reward changes in the rematch.';
  gsap.fromTo('#clash-result',{y:12,opacity:0},{y:0,opacity:1,duration:.4});this.sendPacket(this.timeline.moves[120]);$('clash-countdown').textContent=winner.team?NAMES[winner.team].toUpperCase()+' WINS':'DRAW';$('clash-countdown').style.color=winner.team==='coral'?'#ff9da9':'#75f7d4';gsap.fromTo('#clash-countdown',{opacity:1,scale:.8},{opacity:0,scale:1.1,delay:.5,duration:1.5});
 }
 stop(){this.token++;clearInterval(this.timer);clearTimeout(this.demoTimer);for(const worker of this.workers)worker.terminate();this.workers=[];gsap.killTweensOf('#clash-countdown');$('clash-countdown').textContent='';}
 cancel(restore=true){if(!this.active())return;this.stop();this.phase='idle';document.body.classList.remove('clash-active','clash-racing');$('clash-session').hidden=true;$('clash-start').hidden=false;$('clash-demo').hidden=false;this.hooks.getScene()?.showRival(false);this.hooks.getScene()?.load(this.hooks.getLevel());this.remoteArenaKey=null;this.showtime?.end();this.hooks.onEnd(restore);this.lastPacket=null;if(!this.overlay)this.sync?.postMessage({type:'end'});}
 sendPacket(pair){if(this.overlay)return;$('clash-captain-badge').textContent='CAPTAIN · '+(this.level.captainRule==='surge'?'CROSSCURRENT SURGE':this.level.captainRule==='calm'?'EYE OF THE STORM':'NATIVE CONDITIONS');this.lastPacket={type:'frame',phase:this.paused&&this.phase==='playing'?'paused':this.phase,countdown:this.countdown||null,levelId:this.level.id,captainRule:this.level.captainRule||'native',cardName:this.card?.name||'SEALED KICKOFF',mint:pair.mint,coral:pair.coral,move:pair.move};this.sync?.postMessage(this.lastPacket);}
 receivePacket(data){if(!data.mint?.state||!data.coral?.state)return;$('clash-captain-badge').textContent='CAPTAIN · '+(data.captainRule==='surge'?'CROSSCURRENT SURGE':data.captainRule==='calm'?'EYE OF THE STORM':'NATIVE CONDITIONS');this.remotePhase=data.phase;const scene=this.hooks.getScene();if(!this.active()||this.hooks.getLevel().id!==data.levelId){if(this.hooks.getLevel().id!==data.levelId)this.hooks.setLevel(data.levelId);this.phase='watching';document.body.classList.add('clash-active');this.hooks.onStart();scene?.showRival(true);}const arenaKey=data.levelId+':'+(data.captainRule||'native');if(this.remoteArenaKey!==arenaKey){scene?.load(captainLevel(this.hooks.getLevel(),data.captainRule||'native'));scene?.showRival(true);this.remoteArenaKey=arenaKey;}scene?.setFrame(data.mint,.2,data.phase!=='playing');scene?.setRivalFrame(data.coral,.2,data.phase!=='playing');scene?.setPlaying(data.phase==='playing');$('mint-score').textContent=String(data.mint.state.goals).padStart(2,'0');$('coral-score').textContent=String(data.coral.state.goals).padStart(2,'0');$('clash-card-label').textContent=data.cardName;$('clash-move').textContent=data.move+' / 120';$('match-clock').textContent=data.move+' / 120 MOVES';$('action-label').textContent=data.phase==='result'?'Full time.':data.phase==='coaching'?'Coaches are choosing incentives.':'Coach Clash · live ghost race';if(data.countdown){$('clash-countdown').textContent=data.countdown;gsap.fromTo('#clash-countdown',{opacity:1,scale:.7},{opacity:0,scale:1.15,duration:.9});}else if(data.phase==='result'){const winner=decideWinner(data.mint.state,data.coral.state);$('clash-countdown').textContent=winner.team?NAMES[winner.team].toUpperCase()+' WINS':'DRAW';gsap.fromTo('#clash-countdown',{opacity:1,scale:.8},{opacity:0,scale:1.1,delay:.5,duration:1.5});}}
 export(){if(!this.timeline)return;const data={version:2,display:{coralMirrorX:true,mintGoal:"right",coralGoal:"left"},mode:'Coach Clash',localDemo:this.demo,rehearsal:!!this.showtime?.rehearsal,showtime:this.showtime?.receipt||null,level:this.level,card:this.card,training:{seed:42,episodesPerTeam:10000},recipes:this.recipes,policies:this.policies,results:Object.fromEntries(TEAMS.map(t=>[t,this.timeline.runs[t].stats])),winner:this.timeline.winner,votes:Object.fromEntries(TEAMS.map(t=>[t,this.coaching.votes[t].size])),note:'Independent canonical ghost runs rendered on mirrored team-colored courses, opposite goals, equal conditions and move budgets. Display coordinates: Coral x = width - 1 - canonical x. No physical interference between teams.'};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='medusa-coach-clash-round-'+this.round+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
}
